 const spans=Array.from(pair?.querySelectorAll('.ttc-reading-char')||[]);
 const index=spans.indexOf(characterElement);
 const character=String(characterElement?.textContent||'');
 if(index<0) return lookupReadingSelection(character,dict);
 let best=null,bestSpan=0,bestDistance=Infinity;
 for(const item of dict){
  const term=Array.from(item.h); if(!term.length||term.length>8) continue;
  for(let start=Math.max(0,index-term.length+1); start<=index; start++){
   if(start+term.length>line.length||index>=start+term.length) continue;
   let ok=true; for(let j=0;j<term.length;j++){ if(line[start+j]!==term[j]){ok=false;break;} }
   if(ok){
    const span=term.length, distance=Math.abs((start+(span-1)/2)-index);
    if(span>bestSpan||(span===bestSpan&&distance<bestDistance)){best=item;bestSpan=span;bestDistance=distance;}
   }
  }
 }
 if(!best) return lookupReadingSelection(character,dict);
 const senses=dict.filter(item=>item.h===best.h);
 const list=(senses.length?senses:[best]).map(item=>Object.assign({},item,{_tier:0,_label:'Khớp tại vị trí chọn'}));
 const seenC=new Set(list.map(x=>x.h+'|'+x.p+'|'+x.m));
 if(Array.from(best.h).length>1){ for(const ch of Array.from(best.h)){ for(const cs of dict.filter(x=>x.h===ch)){ const k=cs.h+'|'+cs.p+'|'+cs.m; if(!seenC.has(k)){ seenC.add(k); list.push(Object.assign({},cs,{_tier:2,_label:'Từ cấu thành'})); } } } }
